import { evaluateCondition } from "@/registry/lib/auth/eval";
import type { Condition } from "@/registry/lib/auth/types/condition";
import type { BaseResource } from "@/registry/lib/auth/types/resource";
import type { BaseSubject } from "@/registry/lib/auth/types/subject";

type AccessControlConfig<
	S extends BaseSubject,
	Actions extends Readonly<Array<string>>,
	ResourceMap extends { [K in keyof ResourceMap]: BaseResource<K & string> },
> = {
	actions: Readonly<Array<string>>;
	getConditions: (
		subject: S,
		resource: ResourceMap[keyof ResourceMap]["type"],
		action: Actions[number],
		RequiresResource: boolean,
	) => Promise<Condition<S, ResourceMap[keyof ResourceMap], boolean>[]>;
};
type ActionMethodMap<
	Actions extends Readonly<Array<string>>,
	ResourceMap extends { [K in keyof ResourceMap]: BaseResource<K & string> },
> = {
	[A in Actions[number]]: (
		arg:
			| ResourceMap[keyof ResourceMap]
			| ResourceMap[keyof ResourceMap]["type"],
	) => Promise<boolean>;
};
export class AccessControl<
	S extends BaseSubject,
	Actions extends Readonly<Array<string>>,
	ResourceMap extends { [K in keyof ResourceMap]: BaseResource<K & string> },
> {
	#config: AccessControlConfig<S, Actions, ResourceMap>;
	async #checkAccess(
		subject: S,
		action: Actions[number],
		resource:
			| ResourceMap[keyof ResourceMap]
			| ResourceMap[keyof ResourceMap]["type"],
	): Promise<boolean> {
		try {
			const resourceType =
				typeof resource === "string" ? resource : resource.type;
			const conditions = await this.#config.getConditions(
				subject,
				resourceType,
				action,
				!(typeof resource === "string"),
			);
			if (!conditions.length)
				throw new Error(
					"No conditions/policies found for subject, resource/resource-type combo.",
				);
			const context =
				typeof resource === "string"
					? { subject: subject }
					: {
							subject: subject,
							resource: resource,
						};
			return conditions.some((condition) => {
				return evaluateCondition(condition, context);
			});
		} catch (e) {
			console.error(e);
			return false;
		}
	}
	constructor(config: AccessControlConfig<S, Actions, ResourceMap>) {
		this.#config = config;
	}

	can(subject: S): {
		[A in Actions[number]]: (
			arg:
				| ResourceMap[keyof ResourceMap]
				| ResourceMap[keyof ResourceMap]["type"],
		) => Promise<boolean>;
	} {
		const api: ActionMethodMap<Actions, ResourceMap> = {} as ActionMethodMap<
			Actions,
			ResourceMap
		>;

		for (const action of this.#config.actions) {
			api[action as Actions[number]] = (arg) =>
				this.#checkAccess(subject, action, arg);
		}
		return Object.freeze(api);
	}
}

import includes from "lodash/includes";
import isEqual from "lodash/isEqual";

type BaseNode = { path: string; operator: string; value: unknown };
type BaseCondition =
	| {
			kind: "all";
			all: (BaseNode | BaseCondition)[];
	  }
	| {
			kind: "any";
			any: (BaseNode | BaseCondition)[];
	  };
type BaseContext = {
	subject: Record<string, unknown>;
	resource?: Record<string, unknown>;
};

function resolvePath(context: BaseContext, path: string): unknown {
	const parts = path.replace(/^\$\./, "").split(".");
	return parts.reduce<unknown>((acc, key) => {
		if (acc && typeof acc === "object" && !Array.isArray(acc)) {
			return (acc as Record<string, unknown>)[key];
		}
		return undefined;
	}, context);
}

// Evaluator for a single ConditionNode
function evaluateNode(node: BaseNode, context: BaseContext): boolean {
	const left = resolvePath(context, node.path);
	const right =
		typeof node.value === "string" && node.value.startsWith("$.")
			? resolvePath(context, node.value)
			: node.value;
	const operator = node.operator;
	const now = Date.now();
	switch (operator) {
		case "equal":
			return isEqual(left, right);
		case "notEqual":
			return !isEqual(left, right);

		case "greaterThan":
			return (left as number | Date) > (right as number | Date);
		case "greaterThanInclusive":
			return (left as number | Date) >= (right as number | Date);
		case "lessThan":
			return (left as number | Date) < (right as number | Date);
		case "lessThanInclusive":
			return (left as number | Date) <= (right as number | Date);
		case "elapsedGreaterThan":
			return now - (left as Date).getTime() > (right as number);
		case "elapsedGreaterThanInclusive":
			return now - (left as Date).getTime() >= (right as number);
		case "elapsedLessThan":
			return now - (left as Date).getTime() < (right as number);
		case "elapsedLessThanInclusive":
			return now - (left as Date).getTime() <= (right as number);
		case "remainingGreaterThan":
			return (left as Date).getTime() - now > (right as number);
		case "remainingGreaterThanInclusive":
			return (left as Date).getTime() - now >= (right as number);
		case "remainingLessThan":
			return (left as Date).getTime() - now < (right as number);
		case "remainingLessThanInclusive":
			return (left as Date).getTime() - now <= (right as number);
		case "includes":
			return Array.isArray(left) && includes(left, right);
		case "in":
			return Array.isArray(right) && includes(right, left);
		default:
			throw new Error(`Unsupported operator: ${operator}`);
	}
}

// Evaluator for a Condition tree
export function evaluateCondition(
	condition: BaseCondition,
	context: BaseContext,
): boolean {
	if (condition.kind === "all") {
		return condition.all.every((c) =>
			"kind" in c ? evaluateCondition(c, context) : evaluateNode(c, context),
		);
	} else if (condition.kind === "any") {
		return condition.any.some((c) =>
			"kind" in c ? evaluateCondition(c, context) : evaluateNode(c, context),
		);
	} else return false;
}

import type { OperatorForRelation } from "@/registry/lib/auth/types/operator";
import type { AuthContext } from "@/registry/lib/auth/types/policy";
import type { BaseResource } from "@/registry/lib/auth/types/resource";
import type { BaseSubject } from "@/registry/lib/auth/types/subject";

type Primitive = string | boolean | number | bigint;

type DotPathMap<T, Prefix extends string = ""> = {
	[K in keyof T & string]-?: NonNullable<T[K]> extends Primitive
		? { path: `${Prefix}${K}`; type: NonNullable<T[K]> }
		: NonNullable<T[K]> extends Date
			? { path: `${Prefix}${K}`; type: Date }
			: NonNullable<T[K]> extends Array<infer U>
				? { path: `${Prefix}${K}`; type: Array<U> }
				: NonNullable<T[K]> extends Record<string, unknown>
					? DotPathMap<T[K], `${Prefix}${K}.`>
					: never;
}[keyof T & string];

type ElementType<T> = T extends ReadonlyArray<infer U> ? U : T;

type PathRegistry<
	S extends BaseSubject,
	Resource extends BaseResource<string>,
	RequiresResource extends boolean,
> = DotPathMap<AuthContext<S, Resource, RequiresResource>>;

export type ConditionNode<
	S extends BaseSubject,
	Resource extends BaseResource<string>,
	RequiresResource extends boolean,
> =
	PathRegistry<S, Resource, RequiresResource> extends infer P extends {
		path: string;
		type: Primitive | Date | Array<infer _U>;
	}
		? {
				[K in P as K["path"]]: //literal values
					| {
							path: `$.${K["path"]}`;
							operator: OperatorForRelation<K["type"], K["type"]>;
							value: K["type"];
					  }
					| {
							path: `$.${K["path"]}`;
							operator: OperatorForRelation<K["type"], ElementType<K["type"]>>;
							value: ElementType<K["type"]> extends Date
								? number | ElementType<K["type"]>
								: ElementType<K["type"]>;
					  }
					| {
							path: `$.${K["path"]}`;
							operator: OperatorForRelation<
								K["type"],
								ElementType<K["type"]>[]
							>;
							value: ElementType<K["type"]>[];
					  }
					// value by path
					| {
							path: `$.${K["path"]}`;
							operator: OperatorForRelation<K["type"], K["type"]>;
							value: `$.${Exclude<Extract<P, { type: K["type"] }>["path"], K["path"]>}`;
					  }
					| {
							path: `$.${K["path"]}`;
							operator: OperatorForRelation<K["type"], ElementType<K["type"]>>;
							value: `$.${Exclude<Extract<P, { type: ElementType<K["type"]> }>["path"], K["path"]>}`;
					  }
					| {
							path: `$.${K["path"]}`;
							operator: OperatorForRelation<
								K["type"],
								ElementType<K["type"]>[]
							>;
							value: `$.${Exclude<Extract<P, { type: ElementType<K["type"]>[] }>["path"], K["path"]>}`;
					  };
			}[P["path"]]
		: never;

export type Condition<
	S extends BaseSubject,
	Resource extends BaseResource<string>,
	RequiresResource extends boolean,
> =
	| {
			kind: "all";
			all: (
				| ConditionNode<S, Resource, RequiresResource>
				| Condition<S, Resource, RequiresResource>
			)[];
	  }
	| {
			kind: "any";
			any: (
				| ConditionNode<S, Resource, RequiresResource>
				| Condition<S, Resource, RequiresResource>
			)[];
	  };

import type { Policy } from "@/registry/lib/auth/types/policy";
import type { BaseResource } from "@/registry/lib/auth/types/resource";
import type { BaseSubject } from "@/registry/lib/auth/types/subject";

export type Entitlement<
	S extends BaseSubject,
	Resource extends BaseResource<string>,
	Actions extends Readonly<string[]>,
> = {
	id: number;
	title: string;
	description: string;
	resource: Resource["type"];
	policies: {
		[A in Actions[number]]?:
			| Policy<S, Resource, true>
			| Policy<S, Resource, false>;
	};
};

import type { Condition } from "@/registry/lib/auth/types/condition";
import type { BaseResource } from "@/registry/lib/auth/types/resource";
import type { BaseSubject } from "@/registry/lib/auth/types/subject";

export type AuthContext<
	S extends BaseSubject,
	Resource extends BaseResource<string>,
	RequiresResource extends boolean,
> = RequiresResource extends true
	? { subject: S; resource: Resource }
	: { subject: S };

export type Policy<
	S extends BaseSubject,
	Resource extends BaseResource<string>,
	RequiresResource extends boolean,
> = {
	requiresResource: RequiresResource;
	conditions: Condition<S, Resource, RequiresResource>;
};

export type BaseResource<T extends string> = {
	type: T;
	[key: string]: unknown;
};
export type BaseResourceMap<
	T extends { [K in keyof T]: BaseResource<K & string> },
> = T;
export type WithType<K extends string, T> = T & { type: K };
